// chatbot.cpp - A simple rule-based chatbot
#include <iostream>
#include <string>
using namespace std;

int main() {
    string msg;
    cout << "Bot: Hello! Ask me about the school. Type 'bye' to exit." <<
endl;

    while (true) {
        cout << "You: ";
        getline(cin, msg);

        if (msg == "bye") {
            cout << "Bot: Goodbye! Have a nice day." << endl;
            break;
        } else if (msg.find("time") != string::npos) {
            cout << "Bot: School time is 8 AM to 2 PM." << endl;
        } else if (msg.find("fee") != string::npos) {
            cout << "Bot: Please visit the office for the fee details." <<
endl;
        } else if (msg.find("hello") != string::npos) {
            cout << "Bot: Hi there! How can I help you?" << endl;
        } else {
            cout << "Bot: Sorry, I did not understand that." << endl;
        }
    }
    return 0;
}

// sensor.cpp - IoT smart fan simulation
#include <iostream>
using namespace std;

int main() {
    float temperature;
    cout << "Enter room temperature (in C): ";
    cin >> temperature;

    if (temperature >= 30)
        cout << "Fan speed: HIGH" << endl;
    else if (temperature >= 25)
        cout << "Fan speed: MEDIUM" << endl;
    else if (temperature >= 20)
        cout << "Fan speed: LOW" << endl;
    else
        cout << "Fan: OFF" << endl;
    return 0;
}
